import{_ as t,o as r,c as s,a4 as n}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0016 — Synonymes et mots vides : réécriture de la requête à l'application, jamais un dictionnaire PostgreSQL","description":"Extrait de docs/adr/0016-synonymes-stopwords-reecriture-de-requete.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0016 — Synonymes et mots vides : réécriture de la requête à l'application, jamais un dictionnaire PostgreSQL","description":"Extrait de docs/adr/0016-synonymes-stopwords-reecriture-de-requete.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0016-synonymes-stopwords-reecriture-de-requete.md","filePath":"developpeurs/adr/0016-synonymes-stopwords-reecriture-de-requete.md"}`),i={name:"developpeurs/adr/0016-synonymes-stopwords-reecriture-de-requete.md"};function o(a,e,u,d,c,l){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0016--synonymes-et-mots-vides--réécriture-de-la-requête-à-lapplication-jamais-un-dictionnaire-postgresql" tabindex="-1">ADR-0016 — Synonymes et mots vides : réécriture de la requête à l&#39;application, jamais un dictionnaire PostgreSQL <a class="header-anchor" href="#adr-0016--synonymes-et-mots-vides--réécriture-de-la-requête-à-lapplication-jamais-un-dictionnaire-postgresql" aria-label="Permalink to &quot;ADR-0016 — Synonymes et mots vides : réécriture de la requête à l&#39;application, jamais un dictionnaire PostgreSQL {#adr-0016--synonymes-et-mots-vides--réécriture-de-la-requête-à-lapplication-jamais-un-dictionnaire-postgresql}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §10.1 (autocomplétion, synonymes et stopwords éditables depuis le back-office), §10.2 (configuration linguistique française, deux points d&#39;entrée de recherche), §9 (multi-site), §16.2 (index prêt pour les documents)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC §10.1 exige des <strong>synonymes et des mots vides éditables depuis le back-office et stockés en base, jamais dans un fichier de configuration serveur</strong>. La phrase est courte ; elle écarte à elle seule le mécanisme que PostgreSQL propose pourtant exactement pour cet usage, et le CDC ne dit rien de ce qu&#39;il faut mettre à la place. C&#39;est le point à trancher.</p><p><strong>Ce que PostgreSQL offre nativement, et pourquoi ce n&#39;est pas utilisable ici.</strong> La recherche plein texte de PostgreSQL sait faire des synonymes et des mots vides, par trois moyens :</p><ul><li>un dictionnaire <code>synonym</code> (fichier <code>.syn</code>) ou <code>thesaurus</code> (fichier <code>.ths</code>) monté dans une configuration de recherche ;</li><li>une liste de mots vides (fichier <code>.stop</code>) attachée à un dictionnaire <code>snowball</code> ;</li><li>la fonction <code>ts_rewrite()</code>, qui réécrit un <code>tsquery</code> à partir de règles — et celles-ci, contrairement aux précédentes, <strong>peuvent</strong> vivre dans une table.</li></ul><p>Les deux premiers moyens partagent trois propriétés rédhibitoires pour ce projet :</p><ol><li><strong>Ce sont des fichiers du serveur</strong>, lus dans <code>$SHAREDIR/tsearch_data</code>. Les modifier depuis un back-office signifierait donner à l&#39;application un droit d&#39;écriture sur le système de fichiers du serveur de base de données — ce que le CDC interdit en toutes lettres.</li><li><strong>Ce sont des ressources globales à l&#39;instance.</strong> Une configuration de recherche appartient à une base, se modifie par <code>ALTER TEXT SEARCH CONFIGURATION</code> (propriétaire de la configuration, en pratique le superutilisateur), et s&#39;applique à tout ce qui l&#39;utilise. Sur une instance mutualisée — le mode normal de ce CMS (§9) — le réglage de vocabulaire de la commune A deviendrait celui de la commune B.</li><li><strong>Ils agissent à l&#39;indexation.</strong> Changer la liste de mots vides d&#39;une configuration invalide les <code>tsvector</code> déjà calculés : il faut réindexer. Sur un fonds documentaire extrait par OCR (E9), corriger une coquille dans un synonyme deviendrait une opération d&#39;exploitation planifiée.</li></ol><p>Restent donc deux candidats réels : <strong><code>ts_rewrite()</code> sur des règles stockées en table</strong>, et <strong>la réécriture des termes soumis dans l&#39;application, avant <code>plainto_tsquery</code></strong>.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le vocabulaire d&#39;une organisation agit sur la requête, dans l&#39;application, avant qu&#39;elle n&#39;atteigne PostgreSQL. L&#39;index n&#39;en dépend jamais.</strong></p><p>Concrètement, pour chaque recherche :</p><ol><li>la saisie est repliée et découpée en termes (<code>app/search/normalize.py</code>) ;</li><li>les termes de l&#39;organisation déclarés <strong>mots vides</strong> sont retirés de la liste ;</li><li>les termes qui appartiennent à un <strong>groupe de synonymes</strong> sont remplacés par l&#39;alternative complète du groupe ;</li><li>la liste est assemblée en un <code>tsquery</code> : un OU entre les variantes d&#39;un même terme, un ET entre les termes.</li></ol><p>L&#39;assemblage passe par <code>tsquery_or()</code> / <code>tsquery_and()</code> appliquées à des <code>plainto_tsquery(config, unaccent($1))</code>, chaque terme voyageant en <strong>paramètre lié</strong>. Aucune chaîne <code>tsquery</code> n&#39;est construite par concaténation : le texte vient d&#39;un visiteur, et un <code>!</code> ou un <code>&#39;</code> y deviendrait un opérateur ou une erreur de syntaxe. Les formes fonctionnelles plutôt que les opérateurs <code>&amp;&amp;</code> / <code>||</code> parce que PostgreSQL traite tous les opérateurs d&#39;extension à égalité de précédence, en associativité gauche : <code>a || b &amp;&amp; c</code> s&#39;y lit <code>(a || b) &amp;&amp; c</code>, c&#39;est-à-dire l&#39;inverse de la structure voulue.</p><p>Trois décisions de modélisation accompagnent celle-ci :</p><p><strong>1. Un groupe de synonymes est un ensemble, pas une flèche.</strong> <code>{mairie, hôtel de ville}</code> développe l&#39;un vers l&#39;autre <strong>dans les deux sens</strong>. Une table de correspondances dirigées (<code>source</code>, <code>cible</code>) aurait obligé à saisir chaque paire deux fois, donc à en oublier une — et une équivalence qui ne fonctionne que dans un sens ne se remarque pas : elle donne simplement moins de résultats un jour sur deux.</p><p><strong>2. Le terme soumis reste toujours en tête de son alternative.</strong> Un synonyme élargit une recherche, il ne la détourne pas. Le jour où un agent déclare un groupe erroné, l&#39;usager continue au moins de trouver ce qu&#39;il a réellement tapé.</p><p><strong>3. Un mot vide déclaré par une organisation sort de la requête, pas de l&#39;index.</strong> Il reste dans le <code>search_vector</code> et redevient cherchable dès que la déclaration est retirée. L&#39;inverse — purger l&#39;index — aurait exigé une réindexation à chaque édition, et aurait rendu le mot définitivement introuvable, y compris pour qui le cherche exprès.</p><p><strong>4. La portée est l&#39;organisation ; un <code>site_id</code> ajoute, il ne remplace pas.</strong> <code>site_id NULL</code> = « vaut pour tous les sites de la collectivité ». Une règle portant un <code>site_id</code> s&#39;ajoute aux règles communes pour ce site. La surcharge a été écartée parce qu&#39;elle aurait exigé de désigner un gagnant entre deux listes non ordonnées — question sans bonne réponse, et dont la réponse aurait dû être expliquée dans chaque écran.</p><h3 id="ce-que-cette-décision-rend-possible-et-qui-nétait-pas-gratuit" tabindex="-1">Ce que cette décision rend possible, et qui n&#39;était pas gratuit <a class="header-anchor" href="#ce-que-cette-décision-rend-possible-et-qui-nétait-pas-gratuit" aria-label="Permalink to &quot;Ce que cette décision rend possible, et qui n&#39;était pas gratuit {#ce-que-cette-décision-rend-possible-et-qui-nétait-pas-gratuit}&quot;">​</a></h3><p><strong>La réécriture est explicable.</strong> La réponse de l&#39;API porte ce qui a été développé (<code>expansions</code>) et ce qui a été ignoré (<code>ignored_stopwords</code>). Un usager qui voit remonter « hôtel de ville » alors qu&#39;il a tapé « mairie » lit pourquoi ; un agent qui vient de déclarer un mot vide vérifie qu&#39;il agit. Aucune des deux autres options ne laissait quoi que ce soit à afficher : un dictionnaire serveur et <code>ts_rewrite()</code> opèrent tous deux <strong>à l&#39;intérieur</strong> du moteur de base de données, et ne rendent que le résultat.</p><p><strong>Une recherche vidée de tous ses mots est un cas nommé.</strong> Si l&#39;organisation a déclaré vides tous les mots de la saisie, la requête n&#39;a plus rien à chercher — elle ne doit surtout pas retomber sur « pas de filtre de mots-clés », qui ramènerait tout le catalogue. Le moteur rend zéro résultat avec une clé de message distincte de « aucun résultat ».</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Dictionnaire <code>synonym</code> / <code>thesaurus</code> + fichier <code>.stop</code> dans la configuration <code>french</code></strong></td><td>Écartée sur trois motifs cumulés, dont un seul aurait suffi : ce sont des <strong>fichiers serveur</strong> (le CDC l&#39;interdit explicitement), la configuration est <strong>globale à l&#39;instance</strong> donc partagée entre organisations (§9), et toute modification <strong>invalide les <code>tsvector</code> déjà calculés</strong> donc impose une réindexation du fonds documentaire. C&#39;est pourtant le mécanisme « prévu pour ça » : c&#39;est l&#39;exigence d&#39;édition par organisation depuis un back-office qui le disqualifie, pas sa qualité.</td></tr><tr><td><strong><code>ts_rewrite()</code> sur une table de règles</strong></td><td>Écartée, et c&#39;est le concurrent sérieux. Trois raisons. <strong>(a) Les règles s&#39;écrivent en <code>tsquery</code>, donc en lexèmes racinisés</strong> : le back-office devrait stocker <code>&#39;mairi&#39;</code> et <code>&#39;hotel&#39; &amp; &#39;vill&#39;</code> — formes illisibles pour un agent, non réaffichables telles qu&#39;il les a saisies, et <strong>dépendantes de la version du dictionnaire <code>french_stem</code></strong> de l&#39;instance, donc susceptibles de cesser de correspondre après une mise à jour de PostgreSQL. <strong>(b) La forme « table de règles » (<code>ts_rewrite(query, &#39;SELECT source, target FROM ...&#39;)</code>) réévalue la sous-requête pour chaque règle</strong>, et le filtre d&#39;isolation d&#39;organisation devrait y être injecté dans une chaîne SQL — exactement le genre d&#39;endroit où une barrière d&#39;isolation se troue. <strong>(c) Elle ne sait pas retirer un mot vide</strong> : réécrire un terme vers un <code>tsquery</code> vide n&#39;est pas exprimable proprement, alors que retirer un mot d&#39;une liste en Python est trivial et vérifiable.</td></tr><tr><td><strong>Une configuration de recherche PostgreSQL par organisation</strong> (<code>CREATE TEXT SEARCH CONFIGURATION organization_x…</code>)</td><td>Écartée : elle résoudrait l&#39;isolation, au prix d&#39;un objet de base de données créé par DDL à chaque organisation — donc d&#39;une migration à chaque création de collectivité, et d&#39;un droit DDL accordé au code applicatif. Elle laisserait entières les deux autres objections : fichiers serveur pour les dictionnaires, et réindexation à chaque édition.</td></tr><tr><td><strong>Un fichier de configuration applicatif (YAML) par organisation, comme le Model Registry d&#39;E8</strong></td><td>Écartée : le CDC dit « stockés en base, jamais dans un fichier de configuration serveur », et il a raison ici pour une raison qui distingue ce cas du Model Registry. Un catalogue de modèles IA est déclaré par un <strong>exploitant</strong> qui a accès au serveur ; un vocabulaire de recherche est déclaré par une <strong>chargée de communication</strong> qui a accès à un navigateur. Ce ne sont pas les mêmes mains, donc pas le même support.</td></tr><tr><td><strong>Enrichir le <code>tsvector</code> à l&#39;indexation avec les synonymes</strong> (recopier « hôtel de ville » dans le vecteur de tout contenu contenant « mairie »)</td><td>Écartée : elle donne les meilleurs temps de réponse, et c&#39;est sa seule qualité. Chaque édition du vocabulaire exigerait de réindexer tout le corpus concerné, un synonyme retiré laisserait des vecteurs pollués jusqu&#39;à la réindexation suivante, et la pertinence (<code>ts_rank_cd</code>) serait faussée par des termes que le document ne contient pas.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Éditer le vocabulaire est une écriture de deux lignes en base : <strong>aucune réindexation</strong>, effet immédiat sur la recherche suivante, réversible d&#39;un clic.</li><li>L&#39;isolation entre organisations est celle du reste du CMS — un <code>WHERE organization_id = …</code>, pas une propriété d&#39;un objet global au serveur.</li><li>Le CMS n&#39;exige aucun droit DDL ni aucun accès au système de fichiers du serveur de base de données pour une fonction de back-office.</li><li>La réécriture est restituée dans la réponse : elle est vérifiable par l&#39;agent qui l&#39;a déclarée et compréhensible par l&#39;usager qui la subit.</li><li>L&#39;index reste identique pour toutes les organisations, donc partageable, et la configuration linguistique française (<code>french</code> + <code>unaccent</code>) posée en 0001 reste le seul réglage d&#39;indexation — pluriels et genre continuent d&#39;être traités par <code>french_stem</code>, qui le fait mieux qu&#39;une table maison.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Une requête développée est plus coûteuse</strong> : <code>(mairie | hôtel de ville) &amp; budget</code> interroge l&#39;index GIN sur davantage de lexèmes qu&#39;un terme seul. Le coût croît avec la taille des groupes, d&#39;où la borne de 20 termes par groupe.</li><li><strong>Le vocabulaire est chargé à chaque recherche</strong> (deux <code>SELECT</code> filtrés par organisation). C&#39;est acceptable au volume attendu — un glossaire de collectivité — et ce sera le premier candidat à un cache mémoire si le profil de charge le demande. Le choix de charger plutôt que de filtrer côté base est délibéré : filtrer aurait ajouté un aller-retour par recherche pour économiser une table qui tient dans un cache.</li><li><strong>Les synonymes ne s&#39;appliquent pas à l&#39;autocomplétion.</strong> Taper « mairie » ne propose pas les titres contenant « hôtel de ville » : le complètement travaille sur des préfixes de titres, pas sur des lexèmes. C&#39;est une limite assumée, pas un oubli — la suggestion resterait incohérente avec le préfixe affiché dans le champ.</li><li><strong>Rien n&#39;empêche une organisation de se tirer dans le pied</strong> : déclarer « ville » mot vide sur le site d&#39;une ville rend tous les intitulés en « Ville de… » indiscriminants, ce qui est le but, mais déclarer un mot porteur le rend introuvable. Le garde-fou est la restitution (<code>ignored_stopwords</code> dans la réponse), pas un refus — le CMS n&#39;a pas à savoir mieux que la collectivité quels mots sont vides chez elle.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Écran de back-office (Nuxt) : présenter synonymes et mots vides <strong>côte à côte</strong>, un mot déclaré vide <em>et</em> membre d&#39;un groupe de synonymes étant une incohérence qui ne se voit que si les deux listes sont sous les yeux. La route <code>GET /api/v1/search/dictionaries</code> sert déjà les deux d&#39;un seul appel. — <code>apps/admin/pages/recherche/dictionnaires.vue</code> : un seul écran, chargé d&#39;un seul appel (ligne 50, <code>/api/search/dictionaries</code>), qui présente la section « Synonymes » (ligne 308) puis la section « Mots vides » (ligne 488), l&#39;une sous l&#39;autre. <strong>Décision du Product Owner (audit du 26/09/2026, SUIVI-5)</strong> : l&#39;une sous l&#39;autre sur le même écran suffit, les deux listes sont sous les yeux ensemble.</li><li>[ ] Mesurer le coût du chargement du vocabulaire sous charge réelle avant d&#39;introduire un cache : un cache par organisation devra être invalidé à l&#39;écriture, et un vocabulaire périmé est un défaut plus difficile à diagnostiquer qu&#39;une requête un peu lente.</li><li>[ ] Le jour d&#39;une bascule vers OpenSearch (évolution nommée par le CDC §10.2, hors périmètre de V1.1) : les deux tables restent la source de vérité et se traduisent en filtres de jetons côté moteur d&#39;index — la décision « le vocabulaire est une donnée de l&#39;organisation » survit au changement de moteur, ce qui n&#39;aurait pas été le cas d&#39;un dictionnaire PostgreSQL.</li></ul>',31)])])}const m=t(i,[["render",o]]);export{g as __pageData,m as default};
